function display(v){if(v===undefined||v===null)return '—';if(typeof v==='boolean')return v?'Yes':'No';if(typeof v==='number')return Number.isInteger(v)?fmt(v):String(v);if(typeof v==='object')return Array.isArray(v)?`${v.length} items`:`${Object.keys(v).length} fields`;return String(v)}
function nav(){ $('#datasets').innerHTML=Object.entries(CATALOG).map(([key,c])=>`<button class="nav-item ${kind===key?'active':''}" data-kind="${key}" ${kind===key?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${c.icon}</span><span>${c.title}</span><span class="nav-count">${c.count>=10000?Math.round(c.count/1000)+'k':fmt(c.count)}</span></button>`).join(''); }
async function loadKind(next){if(!CATALOG[next])next='heroes'; clearTimeout(searchTimer); const ticket=++generation;kind=next;rows=[];filtered=[];selected=null;page=0;sortField='';sortDir=1;columns=[...CATALOG[kind].columns];detailMode='fields';document.body.dataset.table=kind;nav();$('#title').textContent=CATALOG[kind].title;$('#eyebrow').textContent=CATALOG[kind].eyebrow;$('#subtitle').textContent=CATALOG[kind].description;$('#total').textContent=fmt(CATALOG[kind].count);$('#search').value='';$('#filter-value').value='';$('#filter-op').value='contains';$('#filter-value').disabled=false;$('#filter-dot').className='';$('#filter-panel').hidden=true;$('#filter-toggle').setAttribute('aria-expanded','false');$('#column-panel').hidden=true;$('#columns-toggle').setAttribute('aria-expanded','false');$('#table-head').innerHTML='';$('#table-body').innerHTML='';$('#empty').hidden=false;$('#empty').textContent='Opening the archive…';$('#result-count').textContent='Loading records…';$('#inspector').innerHTML='<div class="inspector-empty">Loading record details…</div>';$('#inspector').classList.remove('opened');$('#prev').disabled=$('#next').disabled=true;$('#page-label').textContent='';$('#page-number').textContent='';
try{if(!cache[next]){const response=await fetch(`data/${next}.json`);if(!response.ok)throw Error('Could not load this table.');cache[next]=await response.json();idMaps[next]=new Map(cache[next].map(r=>[String(r.id),r]));searchCache[next]=cache[next].map(r=>(String(r.id)+' '+JSON.stringify(r.fields)).toLowerCase());}if(ticket!==generation)return;rows=cache[next];const fields=manifest[next]?.fields||[...new Set(rows.flatMap(r=>Object.keys(r.fields)))].sort();$('#filter-field').innerHTML='<option value="">Choose a field</option><option value="__id">Record ID</option>'+fields.map(f=>`<option value="${esc(f)}">${esc(label(f))} (${esc(f)})</option>`).join('');$('#filter-field').value='';renderColumns(fields);apply();if(filtered.length)selectRecord(filtered[0].id,false);}catch(error){if(ticket!==generation)return;$('#empty').textContent='This table could not be loaded. Please reload the page to try again.';$('#result-count').textContent='Table unavailable';$('#inspector').innerHTML='<div class="inspector-empty">No record loaded.</div>';console.error(error);}}
function renderColumns(fields){$('#column-options').innerHTML=['__id',...fields].map(f=>`<label class="column-option"><input type="checkbox" value="${esc(f)}" ${f==='__id'||columns.includes(f)?'checked':''} ${f==='__id'?'disabled':''}>${f==='__id'?'Record ID':esc(label(f))}</label>`).join('');}
function apply(){const q=$('#search').value.trim().toLowerCase(),field=$('#filter-field').value,op=$('#filter-op').value,val=$('#filter-value').value.trim();const active=!!field&&(op==='exists'||val!=='');filtered=rows.filter((r,i)=>{if(q&&!searchCache[kind][i].includes(q))return false;if(!active)return true;const v=field==='__id'?r.id:r.fields[field];if(op==='exists')return v!==undefined&&v!==null;if(v===undefined||v===null)return false;if(op==='gte'||op==='lte'){if(typeof v!=='number'||!Number.isFinite(Number(val)))return false;return op==='gte'?v>=Number(val):v<=Number(val)}const text=typeof v==='object'?JSON.stringify(v):String(v);return op==='eq'?text.toLowerCase()===val.toLowerCase():text.toLowerCase().includes(val.toLowerCase())});if(sortField)filtered.sort((a,b)=>{const av=sortField==='__id'?a.id:a.fields[sortField],bv=sortField==='__id'?b.id:b.fields[sortField];if(av===undefined||av===null)return bv===undefined||bv===null?0:1;if(bv===undefined||bv===null)return -1;return sortDir*(typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv),undefined,{numeric:true}))});page=0;$('#reset').hidden=!q&&!active;$('#filter-dot').className=active?'on':'';$('#result-count').textContent=`${fmt(filtered.length)} ${q||active?'matching':'available'} records` ;renderTable();}
function cell(key,v){if(v===undefined||v===null)return '<span class="empty-value">—</span>';if(key==='ElementalType')return `<span class="badge element-${esc(v)}">${esc(v)}</span>`;return esc(display(v))}
function renderTable(){const fields=['__id',...columns];$('#table-head').innerHTML='<tr>'+fields.map(f=>`<th scope="col" ${sortField===f?`aria-sort="${sortDir===1?'ascending':'descending'}"`:''}><button data-sort="${esc(f)}">${f==='__id'?'ID':esc(label(f))}${sortField===f?(sortDir===1?' ↑':' ↓'):''}</button></th>`).join('')+'</tr>';const slice=filtered.slice(page*PAGE,(page+1)*PAGE);$('#table-body').innerHTML=slice.map(r=>`<tr data-id="${r.id}" class="${selected?.id===r.id?'selected':''}">${fields.map((f,i)=>{const v=f==='__id'?r.id:r.fields[f];return `<td class="${f==='__id'?'id-cell':f==='Text'?'text-cell':''}">${f==='Name'||f==='Text'||i===0?`<button class="record-link ${f==='__id'?'id-cell':''}" title="${esc(typeof v==='string'?v:String(r.id))}">${esc(f==='Text'?String(v).slice(0,140):display(v))}</button>`:cell(f,v)}</td>`}).join('')}</tr>`).join('');$('#empty').hidden=filtered.length>0;$('#empty').textContent='No matching records. Try another term or clear your filters.';$('#page-label').textContent=filtered.length?`${fmt(page*PAGE+1)}–${fmt(Math.min((page+1)*PAGE,filtered.length))} of ${fmt(filtered.length)}`:'0 records';$('#page-number').textContent=`${filtered.length?page+1:0} / ${Math.ceil(filtered.length/PAGE)}`;$('#prev').disabled=page===0;$('#next').disabled=(page+1)*PAGE>=filtered.length;}
function fieldHTML(key,value,depth=0){if(value!==null&&typeof value==='object'){const array=Array.isArray(value),entries=Object.entries(value);return `<details class="nested"><summary>${esc(label(key))}<span>${entries.length} ${array?'items':'fields'}</span></summary><div class="nested-content">${entries.length?entries.map(([k,v])=>array?`<div class="array-item"><span>ITEM ${Number(k)+1}</span>${typeof v==='object'&&v!==null?Object.entries(v).map(([a,b])=>fieldHTML(a,b,depth+1)).join(''):fieldHTML('Value',v,depth+1)}</div>`:fieldHTML(k,v,depth+1)).join(''):'<span class="muted">Empty</span>'}</div></details>`}const relation=['EvolveTo','OriginId'].includes(key)&&value!==0&&idMaps[kind]?.has(String(value));return `<div class="field"><span class="field-key">${esc(label(key))}${label(key)!==key?`<small>${esc(key)}</small>`:''}</span><span class="field-value ${key==='Text'?'long':''}">${relation?`<button class="relation" data-related="${esc(value)}">${esc(value)} ↗</button>`:esc(display(value))}</span></div>`}
function renderFields(query=''){if(!selected)return;const entries=Object.entries(selected.fields).filter(([k,v])=>!query||(k+' '+JSON.stringify(v)).toLowerCase().includes(query.toLowerCase()));$('#field-list').innerHTML=entries.length?entries.map(([k,v])=>fieldHTML(k,v)).join(''):'<p class="muted">No matching fields.</p>';}
function selectRecord(id,open=true){const r=idMaps[kind]?.get(String(id));if(!r)return;selected=r;const c=CATALOG[kind],title=r.fields.Name?human(r.fields.Name):`Text entry ${r.id}`;$('#inspector').innerHTML=`<div class="detail-top"><div class="record-meta"><span>RECORD DETAILS</span><span>#${r.id}</span></div><button class="close-detail" aria-label="Close record details">×</button><h2>${esc(title)}</h2>${r.fields.Name?`<div class="internal-name">${esc(r.fields.Name)}</div>`:''}${r.fields.ElementalType?`<div style="margin-top:12px">${cell('ElementalType',r.fields.ElementalType)}</div>`:''}</div>${c.stats.length?`<div class="stat-grid">${c.stats.map(k=>`<div class="stat"><span>${esc(label(k))}</span><strong>${esc(display(r.fields[k]))}</strong></div>`).join('')}</div>`:''}<div class="detail-controls"><button data-mode="fields" class="${detailMode==='fields'?'active':''}">All fields <span>(${Object.keys(r.fields).length})</span></button><button data-mode="json" class="${detailMode==='json'?'active':''}">Original JSON</button></div><div id="structured" ${detailMode!=='fields'?'hidden':''}><div class="field-search"><input id="field-search" type="search" placeholder="Find a field or value…" aria-label="Search fields in this record"></div><div class="fields" id="field-list"></div></div><pre class="raw" id="raw" ${detailMode!=='json'?'hidden':''}>${esc(JSON.stringify(r.fields,null,2))}</pre>`;renderFields();if(open)$('#inspector').classList.add('opened');$('#inspector').scrollTop=0;renderTable();}
$('#datasets').addEventListener('click',e=>{const b=e.target.closest('[data-kind]');if(b)location.hash=b.dataset.kind});window.addEventListener('hashchange',()=>loadKind(location.hash.slice(1)));$('#search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(apply,180)});$('#table-head').addEventListener('click',e=>{const b=e.target.closest('[data-sort]');if(!b)return;if(sortField===b.dataset.sort)sortDir*=-1;else{sortField=b.dataset.sort;sortDir=1}apply()});$('#table-body').addEventListener('click',e=>{const row=e.target.closest('[data-id]');if(row)selectRecord(row.dataset.id)});$('#prev').onclick=()=>{if(page>0){page--;renderTable();$('.table-scroll').scrollTop=0}};$('#next').onclick=()=>{if((page+1)*PAGE<filtered.length){page++;renderTable();$('.table-scroll').scrollTop=0}};
for(const p of ['filter','columns']){$('#'+p+'-toggle').onclick=()=>{const target=$('#'+(p==='columns'?'column':p)+'-panel');target.hidden=!target.hidden;$('#'+p+'-toggle').setAttribute('aria-expanded',String(!target.hidden))}}$('#filter-field').onchange=apply;$('#filter-op').onchange=()=>{$('#filter-value').disabled=$('#filter-op').value==='exists';apply()};$('#filter-value').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(apply,180)};$('#clear-filter').onclick=()=>{$('#filter-field').value='';$('#filter-value').value='';apply()};$('#reset').onclick=()=>{$('#search').value='';$('#filter-field').value='';$('#filter-value').value='';apply()};$('#column-options').onchange=()=>{columns=[...$('#column-options').querySelectorAll('input:checked')].map(i=>i.value).filter(k=>k!=='__id');renderTable()};$('#inspector').addEventListener('click',e=>{if(e.target.closest('.close-detail'))$('#inspector').classList.remove('opened');const mode=e.target.closest('[data-mode]');if(mode){detailMode=mode.dataset.mode;$('#structured').hidden=detailMode!=='fields';$('#raw').hidden=detailMode!=='json';$('#inspector').querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===detailMode))}const relation=e.target.closest('[data-related]');if(relation)selectRecord(relation.dataset.related)});$('#inspector').addEventListener('input',e=>{if(e.target.id==='field-search')renderFields(e.target.value)});$('#about').onclick=()=>$('#about-dialog').showModal();$('#about-footer').onclick=()=>$('#about-dialog').showModal();$('.dialog-close').onclick=()=>$('#about-dialog').close();$('#about-dialog').addEventListener('click',e=>{if(e.target===$('#about-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus()}if(e.key==='Escape')$('#inspector').classList.remove('opened')});
async function start(){try{const r=await fetch('data/manifest.json');if(r.ok)manifest=await r.json()}catch{}await loadKind(location.hash.slice(1)||'heroes');const context=document.modelContext;if(context?.registerTool){try{await context.registerTool({name:'search_guardian_records',description:'Select a decoded table and search its records. Updates the visible explorer and returns up to 20 matching record IDs and names.',inputSchema:{type:'object',properties:{table:{type:'string',enum:Object.keys(CATALOG)},query:{type:'string'}},required:['table','query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(!input||!CATALOG[input.table]||typeof input.query!=='string')throw Error('A supported table and text query are required.');if(kind!==input.table){history.replaceState(null,'','#'+input.table);await loadKind(input.table)}$('#search').value=input.query;$('#filter-field').value='';apply();return{count:filtered.length,records:filtered.slice(0,20).map(r=>({id:r.id,name:r.fields.Name||r.fields.Text?.slice(0,120)}))}}})}catch(e){console.warn('Optional browser tools unavailable',e)}}}start();


